def vector_type(inner: TargetType) -> TargetType:
    return TargetType("vector", (inner,))


def map_type(key: TargetType, value: TargetType) -> TargetType:
    return TargetType("map", (key, value))


def set_type(inner: TargetType) -> TargetType:
